import test from 'node:test';
import assert from 'node:assert/strict';
import { dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('dashboard with empty invoices array', () => {
  const result = dashboard([], '2026-10-07');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
  assert.equal(result.outstanding, 0);
  assert.deepEqual(result.overdue, { count: 0, amount: 0 });
  assert.deepEqual(result.topCustomers, []);
});

test('dashboard counts invoices by status', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r1.value, []);
  const invoices = [r2.value, issued.value];
  const result = dashboard(invoices, '2026-10-07');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 0);
  assert.equal(result.counts.paid, 0);
});

test('dashboard calculates outstanding on issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  const result = dashboard(invoices, '2026-10-07');
  assert.ok(result.outstanding > 0);
});

test('dashboard excludes paid invoices from outstanding', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
