  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const totals = invoiceTotals(r2.value);
  const expected = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('invoiceTotals total is reduced by voucher amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const totalsWithout = invoiceTotals(r.value);
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const totalsWith = invoiceTotals(r2.value);
  assert.equal(totalsWith.total, totalsWithout.total - 5000);
});

test('invoiceTotals clamps total to 0 when voucher exceeds total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const totalsWithout = invoiceTotals(r.value);
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: totalsWithout.total + 10000 });
  const totalsWith = invoiceTotals(r2.value);
  assert.equal(totalsWith.total, 0);
});

test('applyVoucher with multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const r2 = applyVoucher(r.value, { code: 'BULK20', amount: 10000 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.voucher.amount, 10000);
});

test('applyVoucher with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const r2 = applyVoucher(r.value, { code: 'EXTRA5', amount: 5000 });
  assert.equal(r2.ok, true);
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.discount, (2 * 8500) * 0.1);
  assert.equal(totals.voucher, 5000);
});

test('applyVoucher preserves other invoice properties', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(r2.value.customerId, r.value.customerId);
  assert.equal(r2.value.issueDate, r.value.issueDate);
  assert.equal(r2.value.status, r.value.status);
  assert.deepEqual(r2.value.lines, r.value.lines);
});

test('applyVoucher can be applied before addLine', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const r3 = addLine(r2.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.voucher.code, 'SAVE10');
  assert.equal(r3.value.lines.length, 2);
});

test('applyVoucher cannot be used on issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  assert.deepEqual(applyVoucher(issued.value, { code: 'SAVE10', amount: 5000 }), { ok: false, error: 'NOT_DRAFT' });
});

test('invoiceTotals voucher is 0 when no voucher applied', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.voucher, 0);
});

